#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXN 100005
#define INF 1000000000

typedef struct {
    int x, y;
} Point;

Point enemies[MAXN];
int minX[2], maxX[2], minY[2], maxY[2];
int W, H, N;

int min(int a, int b) {
    return a < b ? a : b;
}

int max(int a, int b) {
    return a > b ? a : b;
}

int main() {
    scanf("%d %d %d", &W, &H, &N);

    for (int i = 0; i < N; i++) {
        scanf("%d %d", &enemies[i].x, &enemies[i].y);
    }

    // If no enemies, cost is 0
    if (N == 0) {
        printf("0\n");
        return 0;
    }

    // Initialize bounds
    minX[0] = minX[1] = INF;
    maxX[0] = maxX[1] = -INF;
    minY[0] = minY[1] = INF;
    maxY[0] = maxY[1] = -INF;

    // Find bounds for enemies with odd and even parity
    for (int i = 0; i < N; i++) {
        int x = enemies[i].x;
        int y = enemies[i].y;
        int p = (x + y) & 1;

        if (x < minX[p]) minX[p] = x;
        if (x > maxX[p]) maxX[p] = x;
        if (y < minY[p]) minY[p] = y;
        if (y > maxY[p]) maxY[p] = y;
    }

    int ans = INF;

    // Try all 4 combinations of bomb placements
    for (int mask = 0; mask < 4; mask++) {
        int bx[2], by[2];
        int cnt = 0;

        // Determine bomb positions based on mask
        // bit 0: bomb for parity 0, bit 1: bomb for parity 1
        // 0 means bomb at (minX, minY), 1 means bomb at (maxX, maxY)
        for (int p = 0; p < 2; p++) {
            if (minX[p] == INF) continue; // no enemies of this parity
            cnt++;
            if ((mask >> p) & 1) {
                bx[p] = maxX[p];
                by[p] = maxY[p];
            } else {
                bx[p] = minX[p];
                by[p] = minY[p];
            }
        }

        if (cnt == 0) {
            ans = 0;
            continue;
        }

        int cost = 0;
        // Calculate cost for each enemy
        for (int i = 0; i < N; i++) {
            int x = enemies[i].x;
            int y = enemies[i].y;
            int p = (x + y) & 1;

            // Check if this enemy is on the same row or column as its parity's bomb
            if (x == bx[p] || y == by[p]) continue;

            // Need to move to bomb location or to row/column
            int dx = abs(x - bx[p]);
            int dy = abs(y - by[p]);
            cost += min(dx, dy);
        }

        if (cost < ans) ans = cost;
    }

    printf("%d\n", ans);
    return 0;
}

