#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef long long ll;

typedef struct {
    int x, y;
} Point;

static int cmp_int(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    return (x > y) - (x < y);
}

static int lower_bound_int(int *a, int n, int v) {
    int l = 0, r = n;
    while (l < r) {
        int m = (l + r) >> 1;
        if (a[m] < v) l = m + 1;
        else r = m;
    }
    return l;
}

int main(void) {
    int W, H, N;
    if (scanf("%d %d %d", &W, &H, &N) != 3) return 0;

    Point *p = (Point *)malloc((N + 1) * sizeof(Point));
    int *xs = (int *)malloc((N + 1) * sizeof(int));
    int *ys = (int *)malloc((N + 1) * sizeof(int));

    p[0].x = 0; p[0].y = 0;
    xs[0] = 0; ys[0] = 0;

    for (int i = 1; i <= N; i++) {
        scanf("%d %d", &p[i].x, &p[i].y);
        xs[i] = p[i].x;
        ys[i] = p[i].y;
    }

    qsort(xs, N + 1, sizeof(int), cmp_int);
    qsort(ys, N + 1, sizeof(int), cmp_int);

    int xn = 0, yn = 0;
    for (int i = 0; i <= N; i++) {
        if (i == 0 || xs[i] != xs[i - 1]) xs[xn++] = xs[i];
        if (i == 0 || ys[i] != ys[i - 1]) ys[yn++] = ys[i];
    }

    int *xid = (int *)malloc((N + 1) * sizeof(int));
    int *yid = (int *)malloc((N + 1) * sizeof(int));

    for (int i = 0; i <= N; i++) {
        xid[i] = lower_bound_int(xs, xn, p[i].x);
        yid[i] = lower_bound_int(ys, yn, p[i].y);
    }

    const ll INF = (1LL << 60);

    ll *rowMin = (ll *)malloc(xn * sizeof(ll));
    ll *colMin = (ll *)malloc(yn * sizeof(ll));
    ll *best = (ll *)malloc((N + 1) * sizeof(ll));

    for (int i = 0; i < xn; i++) rowMin[i] = INF;
    for (int i = 0; i < yn; i++) colMin[i] = INF;

    /* Start at (0,0): reaching row 0 or column 0 costs 0 */
    rowMin[xid[0]] = 0;
    colMin[yid[0]] = 0;
    best[0] = 0;

    /*
      Key DP:
      If BomBom reaches any enemy at (x,y), bombing there clears row x and column y.
      To reach (x,y), it is enough to come from any already-cleared row x' and move vertically:
          cost = dp(prev) + |x - x'|
      or from any already-cleared column y' and move horizontally:
          cost = dp(prev) + |y - y'|
      Maintain:
          rowMin[x'] = minimum dp(prev) for points on row x'
          colMin[y'] = minimum dp(prev) for points on column y'
      Then for each point:
          dp = min over rows/cols above.
      Since rowMin/colMin only store dp(prev), and movement cost depends only on coordinate
      difference, processing points in arbitrary order is not enough.

      However the state graph is bipartite between rows and columns:
      reaching a point (x,y) activates row x and column y with same cost.
      Distance between rows/columns:
          row x -> col y costs 0 if enemy exists at (x,y)
          row x -> row x' costs |x-x'| via moving along any column already active
      Equivalent shortest path on compressed rows+cols with initial row(0), col(0),
      and zero-cost edges row(x)<->col(y) for every enemy/start point.
      Also complete graph on rows with weight |x-x'|, and on cols with weight |y-y'|.

      In 1D absolute metric, shortest paths can be solved by multi-source Dijkstra where
      transitions among rows/cols are only to adjacent coordinates after sorting.
    */

    int V = xn + yn;
    ll *dist = (ll *)malloc(V * sizeof(ll));
    for (int i = 0; i < V; i++) dist[i] = INF;

    int startR = xid[0];
    int startC = xn + yid[0];
    dist[startR] = 0;
    dist[startC] = 0;

    /* Build enemy incidence lists */
    int *degR = (int *)calloc(xn, sizeof(int));
    int *degC = (int *)calloc(yn, sizeof(int));
    for (int i = 0; i <= N; i++) {
        degR[xid[i]]++;
        degC[yid[i]]++;
    }

    int **adjR = (int **)malloc(xn * sizeof(int *));
    int **adjC = (int **)malloc(yn * sizeof(int *));
    for (int i = 0; i < xn; i++) adjR[i] = (int *)malloc(degR[i] * sizeof(int));
    for (int i = 0; i < yn; i++) adjC[i] = (int *)malloc(degC[i] * sizeof(int));
    memset(degR, 0, xn * sizeof(int));
    memset(degC, 0, yn * sizeof(int));
    for (int i = 0; i <= N; i++) {
        adjR[xid[i]][degR[xid[i]]++] = yid[i];
        adjC[yid[i]][degC[yid[i]]++] = xid[i];
    }

    /* Dijkstra */
    typedef struct { ll d; int v; } Node;
    Node *heap = (Node *)malloc((4 * V + 2 * (N + 1) + 100) * sizeof(Node));
    int hsz = 0;

    #define PUSH(D,V) do { \
        int _i = ++hsz; \
        heap[_i].d = (D); heap[_i].v = (V); \
        while (_i > 1) { \
            int _p = _i >> 1; \
            if (heap[_p].d <= heap[_i].d) break; \
            Node _t = heap[_p]; heap[_p] = heap[_i]; heap[_i] = _t; \
            _i = _p; \
        } \
    } while(0)

    #define POP(res) do { \
        (res) = heap[1]; \
        heap[1] = heap[hsz--]; \
        int _i = 1; \
        while (1) { \
            int _l = _i << 1, _r = _l + 1, _s = _i; \
            if (_l <= hsz && heap[_l].d < heap[_s].d) _s = _l; \
            if (_r <= hsz && heap[_r].d < heap[_s].d) _s = _r; \
            if (_s == _i) break; \
            Node _t = heap[_i]; heap[_i] = heap[_s]; heap[_s] = _t; \
            _i = _s; \
        } \
    } while(0)

    PUSH(0, startR);
    if (startC != startR) PUSH(0, startC);

    char *usedRowZero = (char *)calloc(xn, 1);
    char *usedColZero = (char *)calloc(yn, 1);

    while (hsz) {
        Node cur;
        POP(cur);
        if (cur.d != dist[cur.v]) continue;

        if (cur.v < xn) {
            int r = cur.v;

            if (r > 0) {
                ll nd = cur.d + (ll)(xs[r] - xs[r - 1]);
                if (nd < dist[r - 1]) {
                    dist[r - 1] = nd;
                    PUSH(nd, r - 1);
                }
            }
            if (r + 1 < xn) {
                ll nd = cur.d + (ll)(xs[r + 1] - xs[r]);
                if (nd < dist[r + 1]) {
                    dist[r + 1] = nd;
                    PUSH(nd, r + 1);
                }
            }
            if (!usedRowZero[r]) {
                usedRowZero[r] = 1;
                for (int i = 0; i < degR[r]; i++) {
                    int c = adjR[r][i];
                    int v = xn + c;
                    if (cur.d < dist[v]) {
                        dist[v] = cur.d;
                        PUSH(cur.d, v);
                    }
                }
            }
        } else {
            int c = cur.v - xn;

            if (c > 0) {
                ll nd = cur.d + (ll)(ys[c] - ys[c - 1]);
                if (nd < dist[xn + c - 1]) {
                    dist[xn + c - 1] = nd;
                    PUSH(nd, xn + c - 1);
                }
            }
            if (c + 1 < yn) {
                ll nd = cur.d + (ll)(ys[c + 1] - ys[c]);
                if (nd < dist[xn + c + 1]) {
                    dist[xn + c + 1] = nd;
                    PUSH(nd, xn + c + 1);
                }
            }
            if (!usedColZero[c]) {
                usedColZero[c] = 1;
                for (int i = 0; i < degC[c]; i++) {
                    int r = adjC[c][i];
                    if (cur.d < dist[r]) {
                        dist[r] = cur.d;
                        PUSH(cur.d, r);
                    }
                }
            }
        }
    }

    ll ans = 0;
    for (int i = 1; i <= N; i++) {
        ll d = dist[xid[i]];
        if (dist[xn + yid[i]] < d) d = dist[xn + yid[i]];
        if (d > ans) ans = d;
    }

    printf("%lld\n", ans);

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main(){
    int W, H, N;
    cin >> W >> H >> N;

    set<int> xs, ys;
    for(int i = 0; i < N; i++){
        int x, y;
        cin >> x >> y;
        xs.insert(x);
        ys.insert(y);
    }

    auto minPath1D = [](set<int>& coords) -> int {
        if(coords.empty()) return 0;
        int mn = *coords.begin();
        int mx = *coords.rbegin();
        // start at 0, visit all points
        if(mn >= 0) return mx;
        if(mx <= 0) return -mn;
        return min(mx + (-mn)*2, (-mn) + mx*2);
    };

    cout << minPath1D(xs) + minPath1D(ys) << endl;
    return 0;
}

