struct DSU {
    vector<int> p, sz;
    DSU(int n = 0) { init(n); }
    void init(int n) {
        p.resize(n);
        sz.assign(n, 1);
        iota(p.begin(), p.end(), 0);
    }
    int find(int x) {
        if (p[x] == x) return x;
        return p[x] = find(p[x]);
    }
    void unite(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return;
        if (sz[a] < sz[b]) swap(a, b);
        p[b] = a;
        sz[a] += sz[b];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int W, H, N;
    cin >> W >> H >> N;

    vector<pair<int,int>> enemies(N);
    vector<int> rows, cols;
    rows.reserve(N);
    cols.reserve(N);

    for (int i = 0; i < N; ++i) {
        int x, y;
        cin >> x >> y;
        enemies[i] = {x, y};
        rows.push_back(x);
        cols.push_back(y);
    }

    if (N == 0) {
        cout << 0 << '\n';
        return 0;
    }

    sort(rows.begin(), rows.end());
    rows.erase(unique(rows.begin(), rows.end()), rows.end());
    sort(cols.begin(), cols.end());
    cols.erase(unique(cols.begin(), cols.end()), cols.end());

    int R = rows.size(), C = cols.size();
    DSU dsu(R + C);

    auto rid = [&](int x) {
        return lower_bound(rows.begin(), rows.end(), x) - rows.begin();
    };
    auto cid = [&](int y) {
        return lower_bound(cols.begin(), cols.end(), y) - cols.begin();
    };

    for (auto [x, y] : enemies) {
        dsu.unite(rid(x), R + cid(y));
    }

    unordered_set<int> comps;
    comps.reserve(R + C);
    for (auto [x, y] : enemies) {
        comps.insert(dsu.find(rid(x)));
    }

    bool touchesStart = false;
    if (binary_search(rows.begin(), rows.end(), 0)) {
        int root = dsu.find(rid(0));
        if (comps.count(root)) touchesStart = true;
    }
    if (binary_search(cols.begin(), cols.end(), 0)) {
        int root = dsu.find(R + cid(0));
        if (comps.count(root)) touchesStart = true;
    }

    int ans = (int)comps.size() - (touchesStart ? 1 : 0);
    cout << ans << '\n';
    return 0;
}

