import java.io.*;
import java.util.*;

/*
We need minimum movement cost to visit positions so that every enemy is destroyed.
At any visited cell (x, y), bombing clears all enemies with row = y or column = x.

Equivalent reformulation:
Choose an order of visited cells. Movement cost is Manhattan distance between consecutive
visited cells, starting from (0,0). After visiting selected cells, for every enemy (xi, yi),
at least one visited cell must have x = xi or y = yi.

Observation:
Only enemy x-coordinates and y-coordinates matter. Visiting any other coordinate is useless.
So candidate visited cells are intersections of enemy x's and enemy y's.

Let distinct enemy x's be X[0..nx-1], distinct enemy y's be Y[0..ny-1].
A state can be represented by which x's have been "covered" (visited as column of some chosen cell)
and which y's have been covered. Then an enemy (x,y) is destroyed iff x covered or y covered.

If we move to cell (X[i], Y[j]), we newly cover x i and y j simultaneously.
Movement cost depends on previous chosen cell.

DP over subsets:
dp[maskX][maskY][i][j] = min cost to end at cell (X[i], Y[j]) having covered maskX, maskY.
Transition by moving to a new cell (X[ni], Y[nj]).
Start can move directly from (0,0) to any cell with cost |X[i]| + |Y[j]| = X[i]+Y[j] (coordinates nonnegative on board).

Need final states that destroy all enemies:
for every enemy (xi id, yi id): bit xi in maskX OR bit yi in maskY.

Constraints are not shown, so this subset DP is intended for small number of distinct rows/cols.
We optimize by only considering masks up to 2^nx and 2^ny.

Also handle no enemies => 0.
*/

public class Main {
    static final long INF = (long) 4e18;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        // The statement excerpt omits exact input format.
        // We assume the standard form:
        // W H N
        // then N lines: x y
        //
        // W and H are irrelevant for the optimization except bounding coordinates.
        Integer WObj = fs.nextIntNullable();
        if (WObj == null) return;
        int W = WObj;
        int H = fs.nextInt();
        int N = fs.nextInt();

        int[] ex = new int[N];
        int[] ey = new int[N];

        TreeSet<Integer> xsSet = new TreeSet<>();
        TreeSet<Integer> ysSet = new TreeSet<>();

        for (int k = 0; k < N; k++) {
            ex[k] = fs.nextInt();
            ey[k] = fs.nextInt();
            xsSet.add(ex[k]);
            ysSet.add(ey[k]);
        }

        if (N == 0) {
            System.out.println(0);
            return;
        }

        int nx = xsSet.size();
        int ny = ysSet.size();

        int[] xs = new int[nx];
        int[] ys = new int[ny];
        int p = 0;
        for (int v : xsSet) xs[p++] = v;
        p = 0;
        for (int v : ysSet) ys[p++] = v;

        HashMap<Integer, Integer> xId = new HashMap<>();
        HashMap<Integer, Integer> yId = new HashMap<>();
        for (int i = 0; i < nx; i++) xId.put(xs[i], i);
        for (int j = 0; j < ny; j++) yId.put(ys[j], j);

        int[] exId = new int[N];
        int[] eyId = new int[N];
        for (int k = 0; k < N; k++) {
            exId[k] = xId.get(ex[k]);
            eyId[k] = yId.get(ey[k]);
        }

        int maxMaskX = 1 << nx;
        int maxMaskY = 1 << ny;

        // good[maskX][maskY] = all enemies destroyed?
        boolean[][] good = new boolean[maxMaskX][maxMaskY];
        for (int mx = 0; mx < maxMaskX; mx++) {
            for (int my = 0; my < maxMaskY; my++) {
                boolean ok = true;
                for (int k = 0; k < N; k++) {
                    if (((mx >> exId[k]) & 1) == 0 && ((my >> eyId[k]) & 1) == 0) {
                        ok = false;
                        break;
                    }
                }
                good[mx][my] = ok;
            }
        }

        int cells = nx * ny;
        long[][][] dp = new long[maxMaskX][maxMaskY][cells];
        for (int mx = 0; mx < maxMaskX; mx++) {
            for (int my = 0; my < maxMaskY; my++) {
                Arrays.fill(dp[mx][my], INF);
            }
        }

        // Start transitions
        for (int i = 0; i < nx; i++) {
            for (int j = 0; j < ny; j++) {
                int mx = 1 << i;
                int my = 1 << j;
                int id = i * ny + j;
                dp[mx][my][id] = Math.min(dp[mx][my][id], Math.abs(xs[i]) + Math.abs(ys[j]));
            }
        }

        for (int mx = 0; mx < maxMaskX; mx++) {
            for (int my = 0; my < maxMaskY; my++) {
                for (int id = 0; id < cells; id++) {
                    long cur = dp[mx][my][id];
                    if (cur == INF) continue;

                    int i = id / ny;
                    int j = id % ny;
                    int x = xs[i];
                    int y = ys[j];

                    for (int ni = 0; ni < nx; ni++) {
                        for (int nj = 0; nj < ny; nj++) {
                            int nmx = mx | (1 << ni);
                            int nmy = my | (1 << nj);
                            int nid = ni * ny + nj;
                            long cost = cur + Math.abs(x - xs[ni]) + Math.abs(y - ys[nj]);
                            if (cost < dp[nmx][nmy][nid]) {
                                dp[nmx][nmy][nid] = cost;
                            }
                        }
                    }
                }
            }
        }

        long ans = INF;
        for (int mx = 0; mx < maxMaskX; mx++) {
            for (int my = 0; my < maxMaskY; my++) {
                if (!good[mx][my]) continue;
                for (int id = 0; id < cells; id++) {
                    ans = Math.min(ans, dp[mx][my][id]);
                }
            }
        }

        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        Integer nextIntNullable() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');

            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sgn;
        }

        int nextInt() throws IOException {
            return nextIntNullable();
        }
    }
}
